import{_ as t,o as r,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph (User +) Developer Meeting 2024-11-06","description":"","frontmatter":{"title":"Ceph (User +) Developer Meeting 2024-11-06","date":"2024-11-06T00:00:00.000Z","updated":"2024-11-19T00:00:00.000Z","tags":["Ceph","分布式存储","EL10","RGW快照","开发者会议"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_User_+_Developer_Meeting_2024_-11-06.md","filePath":"posts/2024/Ceph_User_+_Developer_Meeting_2024_-11-06.md","lastUpdated":1780460162000}'),l={name:"posts/2024/Ceph_User_+_Developer_Meeting_2024_-11-06.md"};function n(i,e,p,a,g,_){return r(),o("div",null,[...e[0]||(e[0]=[s('<h3 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h3><p><strong>会议时间</strong>: 2024年11月<br><strong>会议主题</strong>: Ceph开发月度会议 (CDM)<br><strong>参会人员</strong>: Ken, Yehuda, Laura, 以及其他Ceph开发者</p><p><strong>会议议题</strong></p><ol><li><p><strong>Ken: 关于EL10和SELinux的集成</strong></p><ul><li><strong>背景</strong>: 讨论了在CentOS Stream 10 (EL10) 上启用SELinux的挑战和需求。</li><li><strong>目标</strong>: 了解EL10的特性，探讨在EL10上启用SELinux，并讨论如何实现这一目标。</li><li><strong>工作流程</strong>: <ul><li>通过Fedora Rawhide获取缺失的包，进行本地构建和测试。</li><li>使用Copr系统共享RPM包，并逐步将这些包集成到EL10的AppStream中。</li></ul></li><li><strong>挑战</strong>: 需要解决Senta Storage SIG中的NFS Ganesha集成问题，并将EL10集成到Ceph的CI/CD系统中。</li><li><strong>后续行动</strong>: 继续推进EL10的集成工作，特别是与NFS Ganesha的集成，并更新Ceph的容器文件以支持EL10。</li></ul></li><li><p><strong>Yehuda: RGW Bucket Level Snapshots</strong></p><ul><li><strong>背景</strong>: 讨论了在RGW中实现Bucket级别的快照功能的需求。</li><li><strong>目标</strong>: 提出一种基于RGW版本控制系统的Bucket快照方案，避免使用RADOS快照。</li><li><strong>方案</strong>: 在Bucket元数据中维护一个快照ID，每次创建快照时递增该ID，并记录每个对象版本所属的快照ID。</li><li><strong>挑战</strong>: 需要处理非版本化Bucket的快照问题，并优化Bucket索引的扫描性能。</li><li><strong>后续行动</strong>: 继续设计Bucket快照的实现细节，特别是如何处理快照删除时的对象版本管理，并考虑引入生命周期策略。</li></ul></li></ol><p><strong>决定事项</strong></p><ol><li>继续推进EL10的集成工作，特别是与NFS Ganesha的集成。</li><li>设计Bucket快照的实现细节，并考虑引入生命周期策略。</li></ol><p><strong>后续行动计划</strong></p><ol><li>更新Ceph的容器文件，支持EL10作为基础镜像。</li><li>继续设计Bucket快照的实现细节，并考虑引入生命周期策略。</li><li>讨论如何将EL10的包构建和测试集成到Ceph的容器化工作流中。</li></ol><p><strong>其他讨论</strong></p><ul><li>讨论了如何将EL10的包构建和测试集成到Ceph的容器化工作流中。</li><li>讨论了是否可以使用Alma Linux作为上游CI的基础镜像。</li></ul><p><strong>会议结束时间</strong>: 未知 <strong>下次会议时间</strong>: 2024年12月</p>',11)])])}const c=t(l,[["render",n]]);export{h as __pageData,c as default};
